      function CF_PORTFormula return Char is
XBUF VARCHAR2(5000);
begin
	SELECT PORT_NAME INTO XBUF
	FROM SD_PORTS
	WHERE PORT_CD = :PORT_CD;	
	RETURN(XBUF);
EXCEPTION
	WHEN OTHERS THEN RETURN(' ');
end;

      function CF_TYPFormula return Char is
XBUF VARCHAR2(5000) := ' ';
begin
	IF 		:TYP = 1 THEN XBUF := '1- نوع السجل (رئيسي) ورقم السجل الرئيسي غير مدخل   أو رقم السجل الرئيسي والفرعي مدخلان معا.';
	ELSIF :TYP = 2 THEN XBUF := '2- نوع السجل (فرعي) ورقم السجل الفرعي غير مدخل';
	ELSIF :TYP = 3 THEN XBUF := '3- نوع السجل (رئيسي) وطول الرقم لا يساوي 10 خانات';
	ELSIF :TYP = 4 THEN XBUF := '4- نوع السجل (فرعي) وطول الرقم الرئيسي فقط لا يساوي 10 خانات';
	ELSIF :TYP = 5 THEN XBUF := '5- نوع السجل (فرعي ) ورقم السجل الرئيسي والفرعي متساويان';
	ELSIF :TYP = 6 THEN XBUF := '6- الأرقام الأربعة الأولى من رقم السجل الرئيسي لا تطابق (رمز مدينة إصدار السجل)';
	ELSIF :TYP = 7 THEN XBUF := '7- نوع التسجيل في ملف المستوردين (فرعي) ورقم السجل الرئيسي ملف المستوردين  يقابل السجل الفرعي في ملف وزارة التجارة، ورقم السجل الفرعي في ملف المستوردين  يقابل السجل الرئيسي في ملف وزارة التجارة';
	END IF;
	RETURN(XBUF);
EXCEPTION
	WHEN OTHERS THEN RETURN(' ');
end;

      function CF_TYPEFormula return Char is
XBUF VARCHAR2(500);
begin
	IF :BUS_ID_EXPRD_DT > :CF_CURR_DT THEN
 -- XBUF := 'غير منتهي الصلاحية';
 		XBUF := ' ';
		ELSE
		XBUF := 'منتهي الصلاحية';
	END IF;
		RETURN(XBUF);
EXCEPTION
		WHEN OTHERS THEN RETURN(' ');
end;

      function CF_CITYFormula return Char is
XBUF VARCHAR2(5000);
begin
	SELECT MINS_COMM_CD INTO XBUF
	FROM CITIES
	WHERE  CITY_CD = :CITY_CODE_OF_ID
	AND	 CTRY_CD = :CTRY_CD_OF_ID;
	IF LTRIM(RTRIM(XBUF)) = '1'	OR LTRIM(RTRIM(XBUF)) <= ' '	OR LTRIM(RTRIM(XBUF)) IS NULL THEN
		RETURN('غير معروف');
	ELSE
		RETURN(XBUF);
	END IF;
EXCEPTION
	WHEN OTHERS THEN RETURN('غير معروف');
end;

